 "ltfh-BOC": {
  "name": "Ockham (HF · libro)",
  "subject": "hf",
  "block": "B",
  "items": [
   {
    "q": "¿Qué defiende el nominalismo sobre los universales?",
    "o": [
     "Que los universales existen fuera de las cosas, al modo de Platón.",
     "Que los universales son nombres o conceptos generales, no realidades independientes.",
     "Que los universales son formas reales dentro de los cuerpos.",
     "Que los universales están solo en las ideas de Dios."
    ],
    "a": 1,
    "fb": "El nominalismo sostiene que los universales no son realidades independientes, sino nombres o conceptos generales; lo real son las cosas individuales."
   },
   {
    "q": "¿Qué es la \"navaja de Ockham\"?",
    "o": [
     "La exigencia de descartar por completo la razón.",
     "El conflicto filosófico entre la unidad y la pluralidad.",
     "El principio metodológico de no multiplicar entidades sin necesidad.",
     "La tentación de unir nominalismo y realismo."
    ],
    "a": 2,
    "fb": "La navaja de Ockham es el principio metodológico de no multiplicar entidades sin necesidad, limpiando la explicación de lo superfluo."
   },
   {
    "q": "¿Cómo cambia Ockham la relación entre fe y razón?",
    "o": [
     "Separándolas más: la razón no basta para demostrar todas las verdades de la teología.",
     "Uniéndolas del todo, por la vía de la síntesis tomista.",
     "Diciendo que solo debe usarse la razón, apartando la fe.",
     "Mostrando que la fe puede demostrarse mediante la ciencia."
    ],
    "a": 0,
    "fb": "Al subrayar los límites de la razón, Ockham separa más fe y razón: muchas verdades de la teología no se demuestran con la sola razón y quedan en el ámbito de la fe."
   },
   {
    "q": "¿Qué consecuencia trae el nominalismo respecto al conocimiento?",
    "o": [
     "Que el conocimiento mediante experimentos empíricos es imposible.",
     "Que el conocimiento deriva solo de universales estables.",
     "Que el conocimiento está en las formas divinas.",
     "Que el conocimiento parte de la experiencia y de los individuos reales."
    ],
    "a": 3,
    "fb": "Si lo real son los individuos, el conocimiento se desplaza hacia la experiencia y las cosas individuales, no hacia universales estables."
   },
   {
    "q": "¿En qué sentido es Ockham \"la puerta hacia la modernidad\"?",
    "o": [
     "Porque creó directamente la ciencia experimental.",
     "Porque subraya la importancia de los individuos, la economía de la explicación y los límites de la razón.",
     "Porque formuló las bases económicas del capitalismo moderno.",
     "Porque creó el método geométrico del racionalismo."
    ],
    "a": 1,
    "fb": "Ockham anticipa la modernidad al primar los individuos, la economía de la explicación y los límites de la razón, aunque siguiera siendo teólogo medieval."
   }
  ]
 },
