 "ltfh-A1": {
  "name": "En el umbral de la filosofía (HF · libro)",
  "subject": "hf",
  "block": "A",
  "items": [
   {
    "q": "Al hablar de historicidad, ¿qué afirmación es la más precisa?",
    "o": [
     "Las preguntas nacen en contextos, pero algunas reaparecen.",
     "Las preguntas quedan del todo encerradas en cada época.",
     "La filosofía es siempre históricamente neutra.",
     "La historicidad invalida la verdad y la justicia."
    ],
    "a": 0,
    "fb": "La historicidad sitúa cada pregunta en su contexto, pero no encierra a la filosofía en él: cuestiones como la verdad o la justicia reaparecen en épocas distintas."
   },
   {
    "q": "¿Qué es un género filosófico?",
    "o": [
     "El único tipo de texto para analizar conceptos.",
     "Una forma de organizar y expresar el pensamiento.",
     "Una descripción literaria de la condición humana.",
     "La exposición de la verdad lograda por la reflexión."
    ],
    "a": 1,
    "fb": "El género filosófico es la forma escrita o discursiva de organizar y expresar el pensamiento, no un único molde ni una mera descripción literaria."
   },
   {
    "q": "¿Por qué la filosofía no es una mera colección de opiniones?",
    "o": [
     "Porque los seres humanos siempre hemos opinado lo mismo.",
     "Porque las ideas filosóficas excluyen el debate.",
     "Porque examina las opiniones como problemas y argumentos.",
     "Porque se basa únicamente en sentimientos subjetivos."
    ],
    "a": 2,
    "fb": "La filosofía no acumula opiniones sueltas: las examina como problemas y las convierte en argumentos, transformando la opinión en una posición razonable."
   },
   {
    "q": "¿Qué es un método filosófico?",
    "o": [
     "Un modo de ganar un debate sin dar razones.",
     "Un esquema para contar la biografía de un filósofo.",
     "Una técnica para memorizar frases de un autor.",
     "Una manera organizada de trabajar un problema."
    ],
    "a": 3,
    "fb": "Un método filosófico es un procedimiento que organiza preguntas, conceptos y argumentos para trabajar un problema, no un truco retórico ni una técnica memorística."
   },
   {
    "q": "¿Qué es una falacia?",
    "o": [
     "Cualquier opinión defendida filosóficamente.",
     "Un argumento falso pero convincente.",
     "Una opinión personal que no puede probarse.",
     "Una afirmación oscura que nadie entiende."
    ],
    "a": 1,
    "fb": "La falacia es un razonamiento que parece sólido y resulta convincente, pero no justifica debidamente su conclusión."
   },
   {
    "q": "¿Por qué se dice que la historicidad sitúa, pero no encierra, a la filosofía?",
    "o": [
     "Porque cada pregunta nace en un contexto, pero reaparece en otros.",
     "Porque la historia de la filosofía prohíbe reaparecer las preguntas.",
     "Porque la filosofía se hace siempre fuera de toda época.",
     "Porque el contexto anula por completo la pregunta."
    ],
    "a": 0,
    "fb": "La historicidad dice que cada pregunta nace en una época y sociedad concretas, pero no la encierra: cuestiones como la justicia o la verdad reaparecen en culturas y épocas distintas (universalidad)."
   },
   {
    "q": "¿Qué papel juega la transmisión en la historia de la filosofía?",
    "o": [
     "Ninguno: las ideas viajan solas.",
     "Copiar, clasificar y comentar los textos en escuelas e instituciones.",
     "Solo destruir los textos antiguos.",
     "Impedir que se funden nuevas escuelas."
    ],
    "a": 1,
    "fb": "Las escuelas, monasterios, universidades y centros de traducción copiaron, clasificaron y comentaron los textos: muchas ideas sobrevivieron porque una red las transmitió y reinterpretó."
   },
   {
    "q": "¿Qué implica que la elección del «canon» no sea neutra?",
    "o": [
     "Que el canon es siempre completo y definitivo.",
     "Que todos los pensadores entran siempre por igual.",
     "Que la selección de lo «clásico» ha dejado fuera a mujeres filósofas y a pensadores no europeos.",
     "Que el canon no influye en qué se estudia."
    ],
    "a": 2,
    "fb": "El canon ha marginado activamente a mujeres filósofas y a pensadores no europeos, por relaciones de poder patriarcales y colonialistas; revisarlo es un deber de la disciplina."
   },
   {
    "q": "¿Qué expresa el lema socrático «solo sé que no sé nada» en el marco de este tema?",
    "o": [
     "Que quien sabe que no sabe deja de buscar.",
     "Que reconocer la propia ignorancia es el primer paso del saber.",
     "Que la ignorancia es definitiva y no hay forma de aprender.",
     "Que hay que aceptar sin examen toda opinión."
    ],
    "a": 1,
    "fb": "Reconocer la propia ignorancia no es rendirse, sino el punto de partida del saber: quien cree saberlo todo no busca, quien sabe que no sabe investiga."
   },
   {
    "q": "¿Qué tarea distingue a la filosofía de las ciencias según este tema?",
    "o": [
     "La filosofía no dialoga con otros saberes.",
     "Las ciencias y la filosofía son idénticas.",
     "La filosofía usa solo la fe como método.",
     "La filosofía piensa el conjunto y cuestiona los presupuestos que las ciencias dan por supuestos."
    ],
    "a": 3,
    "fb": "Cada ciencia estudia una parcela comprobable; la filosofía se ocupa de preguntas más generales y de los fundamentos que el experimento por sí solo no resuelve."
   }
  ]
 },
